/** The page's own game script, run on HTML inside root; env gives it the page's helpers. */
export function run(root, env) {
  const document = { getElementById: (id) => root.querySelector('#' + id), createElement: (t) => globalThis.document.createElement(t) };
  const { APP_LANG, el, cssVar, safeGet, safeSet, SCX } = env;
  let pushItLangHook = null;
  (function(){
  const levels = [
    { mu:0.3, N:20, label_en:'Wooden crate, smooth floor', label_ta:'மரப்பெட்டி, மினுமினுப்பு தளம்' },
    { mu:0.3, N:40, label_en:'Bigger crate, smooth floor', label_ta:'பெரிய பெட்டி, மினுமினுப்பு தளம்' },
    { mu:0.6, N:20, label_en:'Wooden crate, rough floor', label_ta:'மரப்பெட்டி, கரடுமுரடு தளம்' },
    { mu:0.45, N:60, label_en:'Heavy crate, medium-rough floor', label_ta:'பாரமான பெட்டி, நடுத்தர கரடுமுரடு தளம்' },
    { mu:0.6, N:50, label_en:'Boss level: heavy crate, rough floor!', label_ta:'பாஸ் லெவல்: பாரமான பெட்டி, கரடுமுரடு தளம்!' }
  ];
  const levelRow = document.getElementById('levelRow');
  const levelDesc = document.getElementById('levelDesc');
  const gameSvg = document.getElementById('gameSvg');
  const fSlider = document.getElementById('gameForceSlider');
  const fVal = document.getElementById('gameForceVal');
  const pushBtn = document.getElementById('gamePushBtn');
  const resultEl = document.getElementById('gameResult');
  const starsEl = document.getElementById('gameStars');

  let curLevel = 0;
  let bestStars = JSON.parse(safeGet('scx_pushit_stars') || '[0,0,0,0,0]');

  function drawScene(moved){
    gameSvg.innerHTML = '';
    const x0=40,x1=520,y=45;
    gameSvg.appendChild(el('line',{x1:x0,y1:y,x2:x1,y2:y,stroke:cssVar('--border'),'stroke-width':3}));
    const bx = moved ? x1-60 : x0+20;
    gameSvg.appendChild(el('rect',{x:bx,y:y-16,width:36,height:32,rx:5,fill:cssVar('--accent'),stroke:cssVar('--bg'),'stroke-width':2}));
  }

  function renderLevelRow(){
    levelRow.innerHTML = '';
    levels.forEach((lv,i)=>{
      const b = document.createElement('div');
      b.className = 'level-btn' + (i===curLevel ? ' active' : '');
      const stars = bestStars[i] || 0;
      b.innerHTML = '<div class="lnum2">'+(i+1)+'</div><div class="lstars">'+('★'.repeat(stars)+'☆'.repeat(3-stars))+'</div>';
      b.addEventListener('click', ()=>{ curLevel = i; loadLevel(); });
      levelRow.appendChild(b);
    });
  }

  function loadLevel(){
    renderLevelRow();
    const lv = levels[curLevel];
    levelDesc.textContent = (APP_LANG==='ta') ? lv.label_ta : lv.label_en;
    resultEl.textContent = '';
    resultEl.className = 'game-result';
    starsEl.textContent = '';
    drawScene(false);
  }

  fSlider.addEventListener('input', ()=>{ fVal.textContent = fSlider.value; });

  pushBtn.addEventListener('click', ()=>{
    const lv = levels[curLevel];
    const required = lv.mu * lv.N;
    const F = parseFloat(fSlider.value);
    if(F < required){
      drawScene(false);
      resultEl.textContent = (APP_LANG==='ta') ? '😅 நகரல! இன்னும் அதிக விசை வேணும்.' : "😅 Didn't move! Need more force.";
      resultEl.className = 'game-result lose';
      starsEl.textContent = '';
      SCX.sndWrong();
      return;
    }
    // success — score based on how close to the minimum
    const overshoot = (F - required) / required;
    let stars;
    if(overshoot <= 0.1) stars = 3;
    else if(overshoot <= 0.3) stars = 2;
    else stars = 1;
    drawScene(true);
    resultEl.textContent = (APP_LANG==='ta') ? '🎉 நகர்ந்தது! குறைந்தபட்ச விசை '+required.toFixed(1)+' N இருந்துச்சு.' : '🎉 It moved! The true minimum was '+required.toFixed(1)+' N.';
    resultEl.className = 'game-result win';
    starsEl.textContent = '★'.repeat(stars) + '☆'.repeat(3-stars);

    const prevBest = bestStars[curLevel] || 0;
    if(stars > prevBest){
      bestStars[curLevel] = stars;
      safeSet('scx_pushit_stars', JSON.stringify(bestStars));
      SCX.pushItLevelResult(stars, bestStars.every(s=>s>0));
    } else {
      SCX.sndCorrect();
    }
    renderLevelRow();
  });

  loadLevel();
  pushItLangHook = function(){ levelDesc.textContent = (APP_LANG==='ta') ? levels[curLevel].label_ta : levels[curLevel].label_en; renderLevelRow(); };
})();
  return { lang: () => pushItLangHook && pushItLangHook() };
}
